const route=useRoute(),router=useRouter(),services=ref([]),service=ref(''),cases=ref([]),search=ref(''),moduleFilter=ref(''),tab=ref(['records','suites'].includes(route.query.tab)?route.query.tab:'cases'),editing=ref(false),draft=ref(emptyCase()),saving=ref(false),loading=ref(false),baseline=ref(''),expanded=ref([0]),destroyed=ref(false)
const scenario=computed(()=>!service.value)
const regressionContext=route.query.bug?{bug:route.query.bug,...(route.query.environment?{environment:route.query.environment}:{})}:{}
const editorExpanded=ref(false),canvasFullscreen=ref(false),fullscreenBusy=ref(false),canvasInspectorOpen=ref(false),caseInfoOpen=ref('details')
const documentPicker=ref(null),documentOpening=ref(false)
let documentEpoch=0,documentController
function syncCanvasFullscreen(){canvasFullscreen.value=editing.value&&document.fullscreenElement===document.documentElement}
async function exitCanvasFullscreen(){if(document.fullscreenElement===document.documentElement)await document.exitFullscreen()}
function toggleEditorExpanded(){editorExpanded.value=!editorExpanded.value}
async function toggleCanvasFullscreen(){if(fullscreenBusy.value)return;fullscreenBusy.value=true;try{if(document.fullscreenElement===document.documentElement)await document.exitFullscreen();else{await document.documentElement.requestFullscreen({navigationUI:'hide'});editorView.value='canvas';canvasInspectorOpen.value=false}syncCanvasFullscreen()}catch(e){toast('无法进入画布全屏，请检查浏览器及工作区的全屏权限','error')}finally{fullscreenBusy.value=false}}
function cancelDocument(){documentEpoch++;documentController?.abort();documentPicker.value=null;documentOpening.value=false}
function chooseDocument(stepID=''){
 if(saving.value||draft.value.can_edit===false)return
 if(!stepID&&draft.value.steps.length===1&&!hasCaseRequest(draft.value.steps[0])&&(!draft.value.steps[0].kind||draft.value.steps[0].kind==='http'))stepID=draft.value.steps[0].id
 cancelDocument();documentPicker.value={stepID,initialService:draft.value.steps.find(s=>s.id===stepID)?.service||service.value};canvasInspectorOpen.value=true
}
async function useDocument(row){
 if(documentOpening.value||!documentPicker.value||saving.value||draft.value.can_edit===false)return
 const token=++documentEpoch,id=documentPicker.value.stepID;documentOpening.value=true;documentController=new AbortController()
 try{
  const q=new URLSearchParams({service:row.service,...(row.environment!==undefined?{environment:row.environment}:{})})
  const r=await fetch('api/api-documents/'+encodeURIComponent(row.snapshot_id)+'?'+q,{signal:documentController.signal}),text=await r.text()
  if(!r.ok)throw Error(JSON.parse(text).error||'读取接口定义失败')
  if(token!==documentEpoch||!editing.value)return
  const current=id?draft.value.steps.find(step=>step.id===id):emptyStep()
  if(!current)throw Error('目标节点已移除，请重新选择')
  const value=documentStep(current,row,text,{scenario:scenario.value,service:service.value})
  if(id&&hasCaseRequest(current)&&!await confirmAction('将替换当前节点的名称、请求、参数、自动断言和响应提取。节点连线及操作、预期说明会保留。','使用文档接口'))return
  if(token!==documentEpoch||!editing.value)return
  if(id){const i=draft.value.steps.findIndex(step=>step.id===id);if(i<0)return;draft.value.steps[i]=value;selectNode(i)}
  else{if(draft.value.steps.length>=maxCaseSteps)throw Error(`每个用例最多${maxCaseSteps}个节点`);addStep('http');const i=draft.value.steps.length-1;draft.value.steps[i]={...value,id:draft.value.steps[i].id};selectNode(i)}
  documentPicker.value=null;canvasInspectorOpen.value=true;caseInfoOpen.value='';nextTick(()=>document.querySelector('.case-node-panel')?.scrollIntoView({block:'start'}));toast('已从接口文档填入节点，请核对请求参数和断言','success')
 }catch(e){if(e.name!=='AbortError'&&token===documentEpoch)toast(e.message,'error')}
 finally{if(token===documentEpoch)documentOpening.value=false}
}
onMounted(()=>document.addEventListener('fullscreenchange',syncCanvasFullscreen))
watch(editing,show=>{if(show)syncCanvasFullscreen();else{cancelDocument();exitCanvasFullscreen().catch(()=>{})}})
const editorView=ref('canvas'),selectedNode=ref(''),caseLayout=ref(null),layoutStatus=ref(''),layoutBlocked=ref(false),layoutDirty=ref(false)
let layoutTimer=null,layoutEpoch=0,layoutEditSeq=0
const layoutWorkspace=window.name||'standalone'
const layoutURL=id=>'cases/'+id+'/layout'+scope()+'&workspace='+encodeURIComponent(layoutWorkspace)
let layoutWrite=Promise.resolve()
function persistLayout(id=draft.value.id){clearTimeout(layoutTimer);const epoch=layoutEpoch;layoutWrite=layoutWrite.then(async()=>{if(epoch!==layoutEpoch||!id||!caseLayout.value||layoutBlocked.value||!layoutDirty.value)return;const editSeq=layoutEditSeq,payload=JSON.parse(JSON.stringify(caseLayout.value));const ids=new Set(draft.value.steps.filter(s=>savedNodeIDs.has(s.id)).map(s=>s.id));payload.positions=Object.fromEntries(Object.entries(payload.positions).filter(([id])=>ids.has(id)));layoutStatus.value='正在保存布局';try{const saved=await api(layoutURL(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(epoch===layoutEpoch){caseLayout.value={...caseLayout.value,revision:saved.revision};layoutDirty.value=editSeq!==layoutEditSeq;layoutStatus.value=layoutDirty.value?'布局待保存':'布局已保存'}}catch(e){if(epoch===layoutEpoch){layoutBlocked.value=true;layoutStatus.value='布局未保存';toast(e.message+'；本地布局已保留，请重新读取后核对','warning')}}});return layoutWrite}

function updateLayout(value){layoutDirty.value=true;layoutEditSeq++;caseLayout.value={revision:caseLayout.value?.revision||0,...value};layoutStatus.value=draft.value.id?'布局待保存':'保存用例时保存布局';clearTimeout(layoutTimer);if(draft.value.id&&draft.value.steps.every(s=>savedNodeIDs.has(s.id)))persistLayout()}
let savedNodeIDs=new Set()
async function reloadLayout(){if(!draft.value.id)return;if(!await confirmAction('重新读取将替换当前节点布局，测试内容保持原样。','重新读取布局'))return;try{caseLayout.value=await api(layoutURL(draft.value.id));layoutBlocked.value=false;layoutDirty.value=false;layoutStatus.value='布局已读取'}catch(e){toast(e.message,'error')}}
const impacts=ref([])
const impactCount=id=>impacts.value.filter(r=>r.case_id===id&&r.state==='needs_review').length
const visibilityFilter=ref(''),priorityFilter=ref(''),ownerFilter=ref(''),dataOpen=ref([]),dataEditor=ref(null)
const dirty=computed(()=>editing.value&&baseline.value!==JSON.stringify(draft.value)),modules=computed(()=>moduleTree(cases.value)),filtered=computed(()=>filterCases(cases.value,{search:search.value,module:moduleFilter.value,visibility:visibilityFilter.value,priority:priorityFilter.value,owner:ownerFilter.value})),owners=computed(()=>[...new Set(cases.value.map(c=>c.owner).filter(Boolean))])
const priorities=[{value:'P0',label:'P0 · 最高'},{value:'P1',label:'P1 · 高'},{value:'P2',label:'P2 · 中'},{value:'P3',label:'P3 · 低'}]
const nameInput=ref(null),stepInputs=[],stepRequests=[]
let initialized=false,routeWrites=0
const scope=()=>'?service='+encodeURIComponent(service.value)
async function api(path,options){if(scenario.value)path=path.replace(/^cases(?=[/?]|$)/,'scenario-cases').replace(/^runs(?=[/?]|$)/,'scenario-runs');const r=await fetch('api/api-testing/'+path,options),b=await r.json();if(!r.ok||b.error)throw Error(b.error||'请求失败');return b}
function publish(){document.title=(tab.value==='suites'?'测试集':'测试用例')+(service.value?' · '+service.value:'');if(window.parent!==window){window.parent.postMessage({type:'workspace.label',label:document.title},location.origin);window.parent.postMessage({type:'context.update',service:service.value},location.origin);window.parent.postMessage({type:'context.visibility',service:false,environment:false},location.origin)}routeWrites++;router.replace({path:'/test-cases',query:{...regressionContext,service:service.value,...(tab.value!=='cases'?{tab:tab.value}:{}),...(editing.value&&draft.value.id?{case:String(draft.value.id)}:{})}}).finally(()=>routeWrites--)}
async function leave(){return !dirty.value||await confirmAction('当前用例尚未保存，确认放弃改动？','离开用例编辑')}
async function load(){const app=service.value;loading.value=true;try{const rows=await api('cases'+scope());if(!destroyed.value&&app===service.value){cases.value=Array.isArray(rows)?rows:rows.cases;if(rows.truncated)toast('当前显示最近100个业务场景，可按已知编号打开更早用例','info')}const changes=app?await api('document-impacts'+scope()):[];if(!destroyed.value&&app===service.value)impacts.value=changes}catch(e){toast(e.message,'error')}finally{loading.value=false}}
async function changeService(v){if(!await leave())return;await persistLayout();clearTimeout(layoutTimer);layoutEpoch++;editing.value=false;historyState.value={dirty:false,busy:false};service.value=v||'';moduleFilter.value='';cases.value=[];publish();await load()}
async function edit(c){if(!await leave())return;if(scenario.value&&c?.id){try{c=await api('cases/'+c.id+scope())}catch(e){toast(e.message,'error');return false}}clearTimeout(layoutTimer);const epoch=++layoutEpoch;caseLayout.value=null;layoutBlocked.value=false;layoutDirty.value=false;layoutStatus.value='';draft.value=c?caseDraft(c):{...emptyCase(),...(scenario.value?{scope:'scenario'}:{})};cancelDocument();editorExpanded.value=false;caseInfoOpen.value='details';canvasInspectorOpen.value=false;savedNodeIDs=new Set(draft.value.steps.map(s=>s.id));if(c?.id){try{const layout=await api(layoutURL(c.id));if(epoch!==layoutEpoch)return false;caseLayout.value=layout;layoutStatus.value='布局已读取'}catch(e){layoutBlocked.value=true;layoutStatus.value='布局读取失败';toast(e.message,'error')}}baseline.value=JSON.stringify(draft.value);expanded.value=[0];selectedNode.value=draft.value.steps[0]?.id||'';dataOpen.value=draft.value.data_rows.length?['data']:[];editing.value=true;if(initialized)publish();return true}
async function close(){if(saving.value)return;if(await leave()){await persistLayout();clearTimeout(layoutTimer);layoutEpoch++;editing.value=false;publish()}}
async function save(){if(saving.value||documentOpening.value)return;let payload;try{payload=casePayload(draft.value)}catch(e){canvasInspectorOpen.value=true;if(e.field==='data'||!Number.isInteger(e.stepIndex))caseInfoOpen.value='details';if(e.field==='data'){dataOpen.value=['data'];await nextTick();focusControl(dataEditor.value);document.querySelector('.data-panel')?.scrollIntoView({block:'nearest'})}else if(Number.isInteger(e.stepIndex)){expanded.value=[e.stepIndex];selectedNode.value=draft.value.steps[e.stepIndex]?.id;await nextTick();if(e.field==='service')document.querySelector('[aria-label="步骤 '+(e.stepIndex+1)+' 调用应用"]')?.focus();else if(e.field==='name')focusControl(stepInputs[e.stepIndex]);else await focusControl(stepRequests[e.stepIndex],e.field)}else{await nextTick();focusControl(nameInput.value)}toast(e.message,'warning');return}saving.value=true;try{const c=await api('cases'+(payload.id?'/'+payload.id:'')+scope(),{method:payload.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});draft.value=caseDraft(c);savedNodeIDs=new Set(c.steps.map(s=>s.id));await persistLayout(c.id);baseline.value=JSON.stringify(draft.value);await load();editing.value=false;publish();toast('测试用例已保存','success')}catch(e){toast(e.message,'error')}finally{saving.value=false}}
async function remove(c){if(!await confirmAction('移除后保留该用例的历次执行报告。','删除用例'))return;try{await api('cases/'+c.id+scope(),{method:'DELETE'});await load()}catch(e){toast(e.message,'error')}}
function openExecution(c){const hash='#/test-execution?'+new URLSearchParams({...regressionContext,...(scenario.value?{scope:'scenario'}:{service:service.value}),case:String(c.id)});if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin);else window.open(location.pathname+hash,'_blank','noopener')}
async function duplicate(c){try{if(scenario.value&&c?.id)c=await api('cases/'+c.id+scope());if(await edit(copyCase(c)))baseline.value=''}catch(e){toast(e.message,'error')}}
function changeStepService(step,value){step.service=value;step.application_id=services.value.find(s=>s.name===value)?.application_id||'';step.document_id=0;step.operation_id=''}
async function copyToScenario(c){const app=service.value,next=copyCase(c);next.scope='scenario';next.steps=next.steps.map(s=>(!s.kind||['http','dubbo'].includes(s.kind))?{...s,service:app,application_id:services.value.find(v=>v.name===app)?.application_id||'',document_id:s.document_id||next.document_id}:s);next.document_id=0;if(!await leave())return;service.value='';await load();if(await edit(next))baseline.value=''}
function openScenarioRecords(){const hash='#/test-execution?scope=scenario&view=history&source=case';if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin);else window.open(location.pathname+hash,'_blank','noopener')}
function selectNode(i){selectedNode.value=draft.value.steps[i]?.id;expanded.value=[i]}
function inspectNode(){canvasInspectorOpen.value=true;caseInfoOpen.value='';nextTick(()=>document.querySelector('.case-node-panel')?.scrollIntoView({block:'start'}))}
function addStep(kind='http',position){if(draft.value.steps.length>=maxCaseSteps)return;const hadGraph=!!draft.value.graph,step=emptyStep();if(kind==='dubbo'){step.kind='dubbo';step.name='Dubbo 调用';step.request={method:'DUBBO',path:'/',mode:'dubbo',rpc:{interface:'',method:'',parameter_types:[]},body:'[]',headers:{},timeout_seconds:30,assertions:[{type:'rpc_success',path:'',expected:'true'}]}}else if(kind!=='http'){draft.value.graph ||= linearGraph(draft.value.steps);step.kind=kind;step.name=({condition:'条件判断',parallel:'并行开始',join:'汇合'})[kind];if(kind==='condition')step.condition={variable:'',operator:'equals',expected:{type:'string',value:''}}}const last=draft.value.steps.at(-1);draft.value.steps.push(step);if(!hadGraph&&draft.value.graph&&['http','dubbo','join'].includes(last.kind||'http'))draft.value.graph.edges.push({from:last.id,to:step.id});if(position){const value=caseLayout.value||{positions:{},zoom:1,pan:{x:20,y:28}};updateLayout({...value,positions:{...value.positions,[step.id]:position}})}selectNode(draft.value.steps.length-1)}
function removeStep(i){if(i<0||draft.value.steps.length<=1)return;const [removed]=draft.value.steps.splice(i,1);if(draft.value.graph){draft.value.graph.edges=draft.value.graph.edges.filter(e=>e.from!==removed.id&&e.to!==removed.id);if(draft.value.graph.entry===removed.id)draft.value.graph.entry=draft.value.steps[0].id}selectNode(Math.min(i,draft.value.steps.length-1))}
function connectNodes(from,to,branch=''){try{draft.value.graph=connectGraph(draft.value.graph||linearGraph(draft.value.steps),draft.value.steps,from,to,branch)}catch(e){toast(e.message,'warning')}}
function disconnectNodes(edge){draft.value.graph=disconnectGraph(draft.value.graph||linearGraph(draft.value.steps),edge)}
