const historyConsole=ref(null),historyState=ref({dirty:false,busy:false})
async function closeRecords(){if(historyState.value.busy)return;if(historyConsole.value&&!await historyConsole.value.canCloseHistory())return;historyState.value={dirty:false,busy:false};tab.value='cases'}
watch([dirty,saving,historyState],()=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:dirty.value||historyState.value.dirty,busy:saving.value||historyState.value.busy},location.origin)})
