async function applySelection(q){if(q.case){const c=cases.value.find(v=>v.id===Number(q.case))||(scenario.value?await api('cases/'+encodeURIComponent(q.case)+scope()):null);if(c){await edit(c);if(q.seed_run){const run=await api('runs/'+encodeURIComponent(q.seed_run)+scope()),seed=reportFieldDraft(draft.value,run,{index:Number(q.seed_step),kind:q.seed_kind,path:q.seed_path,name:q.seed_name,event:q.seed_event,select:q.seed_select}),i=seed.index,rows=seed.kind==='extraction'?draft.value.steps[i].extractions:draft.value.steps[i].request.assertions;rows.push(seed.value);expanded.value=[i];await nextTick();await focusControl(stepRequests[i],seed.kind==='extraction'?'extractions':'checks',rows.length-1);toast('已加入用例草稿，请核对后保存；历史报告不会改变','success')}}}if(service.value&&q.snapshot&&q.operation){const r=await fetch('api/api-documents/'+encodeURIComponent(q.snapshot)+scope()),d=await r.json();if(!r.ok)throw Error(d.error);const op=d.operations.find(o=>o.id===q.operation);if(op){await edit();const seed=operationDraft(op,d.document);draft.value.name=op.summary||op.path;draft.value.document_id=d.id;draft.value.steps[0]={...emptyStep(),document_id:d.id,operation_id:op.id,name:op.summary||'接口验证',...requestDraft(seed.request,{pathValues:seed.pathValues,queryRows:seed.query})};baseline.value=''}}}
onMounted(async()=>{try{const q={...route.query};services.value=await fetch('api/services').then(r=>r.json());service.value=services.value.some(s=>s.name===q.service)?q.service:'';await load();await applySelection(q);initialized=true;publish()}catch(e){initialized=true;toast(e.message,'error')}})
watch(()=>route.fullPath,async()=>{
 if(!initialized||routeWrites)return
 const q={...route.query},nextTab=['records','suites'].includes(q.tab)?q.tab:'cases',nextService=String(q.service||'')
 if(nextService===service.value&&nextTab===tab.value&&(!q.case||Number(q.case)===draft.value.id)&&!q.seed_run&&!q.snapshot)return
 if(tab.value==='records'&&(nextTab!==tab.value||nextService!==service.value)&&(historyState.value.busy||historyConsole.value&&!await historyConsole.value.canCloseHistory())){publish();return}
 if(!await leave()){publish();return}
