 try{if(nextService!==service.value){service.value=nextService;cases.value=[];await load()}editing.value=false;tab.value=nextTab;if(nextTab==='cases')await applySelection(q);publish()}catch(e){toast(e.message,'error')}
})
onBeforeUnmount(()=>{destroyed.value=true;clearTimeout(layoutTimer);layoutEpoch++;cancelDocument();document.removeEventListener('fullscreenchange',syncCanvasFullscreen);exitCanvasFullscreen().catch(()=>{})})

import OptionPicker from '../shared/components/OptionPicker.vue'

