<template><TestSuites v-if="tab==='suites'&&!scenario" :service="service" :cases="cases" :regression-context="regressionContext" @back="tab='cases'"/><main v-else class="case-page"><PageSurface><PageHeader title="测试用例" help="用例按业务场景编写，保存后选择环境执行；步骤与断言决定自动执行结果。"><template #actions><Button v-if="!scenario" @click="tab='suites'" variant="outline" size="default" type="button">测试集</Button><Button @click="scenario?openScenarioRecords():tab='records'" variant="outline" size="default" type="button">用例执行记录</Button><Button @click="edit()" variant="default" size="default" type="button">新建用例</Button></template><template #context><OptionPicker :model-value="service" @update:model-value="changeService" all-label="业务场景（可跨应用）" placeholder="选择用例范围" aria-label="用例范围" style="width:220px" :options="services.map(applicationOption)"/></template></PageHeader><p v-if="regressionContext.bug" class="regression-hint"><Badge :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">回归 Bug #{{regressionContext.bug}}</Badge> 选择用例后再执行，执行结果将关联到该 Bug。</p><section class="min-w-0"><div class="filters"><InputGroup style="width:300px" class="min-w-0 "><InputGroupInput v-model="search" placeholder="搜索用例名称、编号或模块" aria-label="搜索测试用例"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup>
<CaseModulePicker v-model="moduleFilter" :items="modules"/>
<OptionPicker v-model="visibilityFilter" placeholder="全部共享范围" aria-label="用例共享筛选" style="width:160px" :options="visibilityOptions" all-label="全部共享范围"/><OptionPicker v-model="priorityFilter" placeholder="全部优先级" style="width:140px" :options="priorities" all-label="全部优先级"/><OptionPicker v-model="ownerFilter" placeholder="全部创建人" style="width:160px" :options="owners" all-label="全部创建人"/><Button @click="load" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新</Button></div><div class="min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:850}).y?({x:850}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:1160}).x||({x:1160}).minWidth||1160)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(100)+'px'}">编号</TableHead><TableHead>用例名称</TableHead><TableHead :style="{width:(150)+'px'}">所属模块</TableHead><TableHead :style="{width:(90)+'px'}">优先级</TableHead><TableHead :style="{width:(150)+'px'}">共享 / 创建人</TableHead><TableHead :style="{width:(130)+'px'}">步骤 / 数据组</TableHead><TableHead :style="{width:(75)+'px'}">版本</TableHead><TableHead :style="{width:(210)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (filtered||[]).slice((_view1-1)*(_view1Size),_view1*(_view1Size))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">TC-{{record.id}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="edit(record)" class="case-name" variant="ghost" size="default" type="button">{{record.name}}</Button><div v-if="scenario" class="case-owner">{{record.services?.join(' / ')}}</div><Badge v-if="impactCount(record.id)" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">{{impactCount(record.id)}} 项文档变更待复核</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["module"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge variant="secondary">{{record.priority||'P2'}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge variant="secondary">{{record.visibility==='team'?'团队可用':'仅自己'}}</Badge><div class="case-owner">{{record.owner}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.step_count||record.steps?.length||1}} 步<template v-if="record.data_count||record.data_rows?.length"> · {{record.data_count||record.data_rows?.length}} 组</template></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">v{{record.revision}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div :size="0" class="flex flex-wrap items-center gap-2"><Button @click="openExecution(record)" variant="ghost" size="default" type="button">执行</Button><Button v-if="record.can_edit" @click="edit(record)" variant="ghost" size="default" type="button">编辑</Button><DropdownMenu><DropdownMenuTrigger as-child><Button variant="ghost" size="default" type="button">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem @select="duplicate(record)">复制用例</DropdownMenuItem><DropdownMenuItem v-if="!scenario" @select="copyToScenario(record)">复制为跨应用场景</DropdownMenuItem><DropdownMenuItem v-if="record.can_edit" @select="remove(record)">删除用例</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></template></div></TableCell></TableRow></template><TableRow v-if="!(filtered||[]).length"><TableCell :colspan="8"><Empty><EmptyHeader><EmptyDescription>{{"暂无用例，可新建或从接口文档生成"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="_view1" :total="(filtered||[]).length" :page-size="_view1Size" @update:page="_view1=$event;" @update:page-size="_view1Size=$event;_view1=1" :disabled="loading"/></div></section></PageSurface></main><Sheet :open="editing" @update:open="value=>{if(!value)close()}"><SheetContent class="case-editor gap-0" :data-editor-expanded="editorExpanded" :data-canvas-fullscreen="canvasFullscreen" :class="editorExpanded||canvasFullscreen?'h-dvh data-[side=right]:w-screen data-[side=right]:sm:max-w-none':'data-[side=right]:w-full data-[side=right]:sm:max-w-[min(64rem,94vw)]'" :show-close-button="!saving" @escape-key-down="event=>{if(saving)event.preventDefault();else if(canvasFullscreen){event.preventDefault();exitCanvasFullscreen()}else if(documentPicker){event.preventDefault();cancelDocument()}else if(editorExpanded){event.preventDefault();editorExpanded=false}}" @interact-outside="event=>{if(saving)event.preventDefault()}"><SheetHeader class="case-editor-header shrink-0 border-b p-4 pr-12"><div class="flex min-w-0 items-center gap-2"><SheetTitle class="min-w-0 flex-1"><EditorDialogTitle :title="draft.id?(draft.can_edit===false?'查看测试用例 · TC-':'编辑测试用例 · TC-')+draft.id:'新建测试用例'" :fullscreen="editorExpanded" expand-label="全屏侧窗" collapse-label="还原侧窗" @toggle="toggleEditorExpanded"/></SheetTitle></div><SheetDescription class="sr-only">编写用例信息、测试步骤和断言</SheetDescription></SheetHeader><div class="case-editor-body min-h-0 flex-1 overflow-hidden p-3"><fieldset :disabled="saving||draft.can_edit===false" class="case-editor-fields h-full min-h-0 min-w-0"><div class="steps-title"><h3>测试步骤</h3><Button type="button" :variant="editorView==='canvas'?'default':'outline'" size="sm" @click="editorView='canvas'">画布</Button><Button type="button" :variant="editorView==='steps'?'default':'outline'" size="sm" @click="editorView='steps'">步骤列表</Button><HelpTip text="按顺序执行，每步在下方配置请求和自动断言。文字预期供人员核对，不作为自动通过依据。登录 Token 复用环境认证。响应提取可把本步骤的返回字段传给后续步骤，例如 {{step.order_id}}。"/><Badge v-if="draft.document_id" variant="secondary">文档快照 #{{draft.document_id}}</Badge></div><CaseEditorWorkspace class="min-h-0 flex-1" :canvas-only="canvasFullscreen&&!canvasInspectorOpen" :inspector-only="editorView==='steps'&&!canvasFullscreen"><template #canvas><div class="case-flow-panel"><div v-if="layoutStatus" class="flex flex-wrap items-center gap-2 text-xs text-muted-foreground"><span>{{layoutStatus}}</span><Button v-if="layoutBlocked&&draft.id" type="button" variant="ghost" size="sm" @click="reloadLayout">重新读取布局</Button></div><TestFlowCanvas v-show="editorView==='canvas'" expandable :fullscreen="canvasFullscreen" :fullscreen-busy="fullscreenBusy" @toggle-fullscreen="toggleCanvasFullscreen" @disconnect="disconnectNodes" @inspect="inspectNode" :steps="draft.steps" :graph="draft.graph" :layout="caseLayout" :selected="selectedNode" :disabled="saving||documentOpening||draft.can_edit===false" @select="selectNode" @connect="connectNodes" @add="addStep" @remove="removeStep" @layout="updateLayout" @add-document="chooseDocument()"><template #tools><Button v-if="canvasFullscreen" variant="outline" size="sm" @click="canvasInspectorOpen=!canvasInspectorOpen">{{canvasInspectorOpen?'收起节点配置':'显示节点配置'}}</Button><Button v-if="canvasFullscreen&&draft.can_edit!==false" size="sm" :disabled="saving||documentOpening" @click="save"><Spinner v-if="saving"/>保存用例</Button></template></TestFlowCanvas></div></template><template #inspector><CaseDocumentPicker v-if="documentPicker" :key="documentPicker.stepID||'new'" :service="scenario?'':service" :initial-service="documentPicker.initialService" :services="services" :opening="documentOpening" @choose="useDocument" @close="cancelDocument"/><div v-show="!documentPicker" class="space-y-4"><DocumentImpact v-if="draft.id&&!scenario&&!canvasFullscreen" :service="service" :case-id="draft.id" :disabled="dirty||saving"/><Accordion class="case-info-panel" type="single" collapsible v-model="caseInfoOpen"><AccordionItem value="details"><AccordionTrigger>用例信息</AccordionTrigger><AccordionContent force-mount v-show="caseInfoOpen==='details'"><div class="space-y-5"><div class="basic-grid"><Field><FieldLabel>用例名称 <span class="text-destructive">*</span></FieldLabel><Input ref="nameInput" v-model="draft.name" placeholder="例如：查询存在的订单，返回订单详情" aria-label="用例名称" :maxlength="200"/></Field><Field><FieldLabel>所属模块</FieldLabel><Input v-model="draft.module" placeholder="例如：订单/订单查询" aria-label="用例所属模块"/></Field><Field><FieldLabel>优先级</FieldLabel><OptionPicker v-model="draft.priority" aria-label="用例优先级" class="min-w-36" :options="priorities"/></Field><Field><FieldLabel>共享范围</FieldLabel><OptionPicker v-model="draft.visibility" aria-label="用例共享范围" class="min-w-36" :options="visibilityOptions"/><template #help><HelpTip text="团队可用后，其他成员可以查看、执行和复制。原作者及管理员可修改；执行报告仍归执行人。请确认请求模板中不含个人凭据。"/></template></Field></div><div class="two-columns"><Field><FieldLabel>前置条件</FieldLabel><Textarea v-model="draft.preconditions" placeholder="例如：测试账号具备订单查询权限；目标订单已存在" aria-label="前置条件" :rows="({minRows:3,maxRows:6}).minRows||4"/></Field><Field><FieldLabel>测试数据</FieldLabel><Textarea v-model="draft.test_data" placeholder="例如：订单编号 7。执行参数请同时填写在对应步骤中" aria-label="测试数据" :rows="({minRows:3,maxRows:6}).minRows||4"/></Field></div><Accordion class="data-panel" type="multiple" :model-value="(dataOpen||[]).map(String)" @update:model-value="dataOpen=$event;"><AccordionItem item-key="data" :value="String(&quot;data&quot;)"><AccordionTrigger>详细设置</AccordionTrigger><AccordionContent force-mount v-show="!(!(dataOpen||[]).map(String).includes(String(&quot;data&quot;)))"><DataSetEditor ref="dataEditor" v-model="draft.data_rows" :disabled="saving||draft.can_edit===false"/></AccordionContent></AccordionItem></Accordion></div></AccordionContent></AccordionItem></Accordion><div class="case-node-panel"><div v-if="draft.graph" class="space-y-3"><div class="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>流程入口</FieldLabel><OptionPicker v-model="draft.graph.entry" :options="draft.steps.map(s=>({value:s.id,label:s.name||s.id}))" aria-label="流程入口"/></Field><Field><FieldLabel>最大并发</FieldLabel><OptionPicker v-model="draft.graph.concurrency" :options="[1,2,3,4].map(n=>({value:n,label:String(n)}))" aria-label="最大并发"/></Field></div></div><Accordion type="multiple" :model-value="(expanded||[]).map(String)" @update:model-value="expanded=$event.map(Number);"><AccordionItem v-for="(step,i) in draft.steps" :key="step.id" v-show="editorView==='steps'||step.id===selectedNode" :item-key="step.id" :value="String(i)"><AccordionTrigger>{{i+1}} · {{step.name||'未命名接口'}}</AccordionTrigger><AccordionContent force-mount v-show="!(!(expanded||[]).map(String).includes(String(i)))"><template #extra><Button @click.stop="move(i,-1)" variant="ghost" size="sm" type="button" :disabled="(i===0||saving||draft.can_edit===false)">上移</Button><Button @click.stop="move(i,1)" variant="ghost" size="sm" type="button" :disabled="(i===draft.steps.length-1||saving||draft.can_edit===false)">下移</Button><Button @click.stop="removeStep(i)" class="text-destructive" :variant="'destructive'" size="sm" type="button" :disabled="(draft.steps.length===1||saving||draft.can_edit===false)">移除</Button></template><Field v-if="scenario&&(!step.kind||['http','dubbo'].includes(step.kind))"><FieldLabel>调用应用 <span class="text-destructive">*</span></FieldLabel><OptionPicker :model-value="step.service" :options="services.map(applicationOption)" :aria-label="'步骤 '+(i+1)+' 调用应用'" placeholder="选择此节点调用的应用" @update:model-value="changeStepService(step,$event)"/></Field><Field><FieldLabel>步骤名称 <span class="text-destructive">*</span></FieldLabel><Input :ref="el=>stepInputs[i]=el" v-model="step.name" placeholder="例如：查询订单详情" :aria-label="'步骤 '+(i+1)+' 名称'"/></Field><div class="two-columns"><Field><FieldLabel>操作步骤</FieldLabel><Textarea v-model="step.action" placeholder="描述本步操作和输入" :aria-label="'步骤 '+(i+1)+' 操作'" :rows="({minRows:2,maxRows:5}).minRows||4"/></Field><Field><FieldLabel>预期结果</FieldLabel><Textarea v-model="step.expected" placeholder="例如：返回订单详情，订单编号与输入一致" :aria-label="'步骤 '+(i+1)+' 预期结果'" :rows="({minRows:2,maxRows:5}).minRows||4"/></Field></div><FlowCondition v-if="step.kind==='condition'" :condition="step.condition" :disabled="saving||draft.can_edit===false"/><StepDocumentLink v-if="!step.kind||['http','dubbo'].includes(step.kind)" :service="scenario?step.service:service" :step="step" :fallback-document="draft.document_id" :disabled="saving||documentOpening||draft.can_edit===false" @select="chooseDocument(step.id)"/><CaseRequest v-if="!step.kind||['http','dubbo'].includes(step.kind)" :ref="el=>stepRequests[i]=el" :step="step" :disabled="saving||draft.can_edit===false" :available="draft.steps.slice(0,i).flatMap(s=>(s.extractions||[]).map(e=>e.name).filter(Boolean))"/></AccordionContent></AccordionItem></Accordion><Button @click="addStep('http')" class="add-step" variant="outline" size="default" type="button" :disabled="(draft.steps.length>=maxCaseSteps||saving||draft.can_edit===false)">添加步骤</Button></div></div></template></CaseEditorWorkspace></fieldset></div><SheetFooter class="case-editor-footer"><Button @click="close" variant="outline" :disabled="saving">{{draft.can_edit===false?'关闭':'取消'}}</Button><Button v-if="draft.can_edit===false" @click="duplicate(draft)">复制为我的用例</Button><Button v-else @click="save" :disabled="saving||documentOpening"><Spinner v-if="saving"/>保存用例</Button></SheetFooter></SheetContent></Sheet>
<Sheet :open="tab==='records'" @update:open="value=>{if(!value)closeRecords()}"><SheetContent class="gap-0 data-[side=right]:w-full data-[side=right]:sm:max-w-[min(72rem,96vw)]" :show-close-button="!historyState.busy" @escape-key-down="event=>{if(historyState.busy)event.preventDefault()}" @interact-outside="event=>{if(historyState.busy)event.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>用例执行记录</SheetTitle><SheetDescription class="sr-only">查看用例执行历史和报告，关闭后保留原列表</SheetDescription></SheetHeader><div class="case-records min-h-0 flex-1 overflow-y-auto"><TestConsole ref="historyConsole" v-if="tab==='records'" :key="service" :records-only="true" :embedded-history="true" :record-service="service" @back="closeRecords" @history-state="historyState=$event" @service-change="changeService"/></div><SheetFooter><Button variant="outline" @click="closeRecords" :disabled="historyState.busy">关闭记录</Button></SheetFooter></SheetContent></Sheet></template>
<style scoped>.case-page{height:100dvh;min-width:0;width:100%;overflow:auto;box-sizing:border-box;background:var(--bg);color:var(--text)}.filters,.steps-title{display:flex;gap:12px;align-items:center;margin-bottom:20px;flex-wrap:wrap}.basic-grid{display:grid;grid-template-columns:minmax(220px,2fr) minmax(160px,1fr) 130px 150px;gap:20px}.two-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.steps-title h3{margin:0;font-size:1.125rem}.add-step{margin-top:16px}.case-owner{margin-top:6px;color:var(--muted-foreground)}.data-panel{margin-bottom:20px}.case-name{max-width:100%;white-space:normal;text-align:left;justify-content:flex-start}@media(max-width:1100px){.basic-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.basic-grid,.two-columns{grid-template-columns:1fr}}</style>

<style scoped>.regression-hint{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:16px;color:var(--muted-foreground)}</style>

<style scoped>.case-records :deep(.api-testing){height:100%;min-height:0;overflow:auto}</style>

<style scoped>
.case-editor-body,.case-editor-fields{height:100%;min-height:0}.case-editor-fields{display:flex;flex-direction:column;gap:8px}.case-editor-fields>.steps-title{flex-shrink:0;margin-bottom:0;gap:8px}.case-flow-panel{display:flex;flex:1;flex-direction:column;min-height:0;min-width:0;gap:8px}.case-flow-panel .steps-title{flex-shrink:0;margin-bottom:0;gap:8px}.case-flow-panel :deep(.test-flow){display:flex;flex:1;flex-direction:column;min-height:0}.case-flow-panel :deep(.flow-viewport){height:auto;flex:1;min-height:130px}.case-info-panel,.case-node-panel{min-width:0}.case-editor-fields .basic-grid,.case-editor-fields .two-columns{grid-template-columns:1fr}.case-editor[data-canvas-fullscreen=true] .case-editor-header,.case-editor[data-canvas-fullscreen=true] .case-editor-footer,.case-editor[data-canvas-fullscreen=true] .steps-title{display:none}.case-editor[data-canvas-fullscreen=true] .case-editor-body{padding:8px}.case-editor[data-canvas-fullscreen=true]>:deep(button[data-slot=sheet-close]){display:none}
</style>
